#include "../src/microvm/gui/NativeGuiBroker.h"
#include <Windows.h>
#include <iostream>
#include <stdexcept>
namespace n=guardian::nativegui;using av::microvm::native_gui::Broker;
namespace {unsigned checks=0;void Check(bool ok,const char* message){++checks;if(!ok)throw std::runtime_error(message);}
size_t Windows(uint32_t pid){struct State{uint32_t pid;size_t count;}state{pid,0};EnumWindows([](HWND h,LPARAM raw)->BOOL{auto& s=*reinterpret_cast<State*>(raw);DWORD process=0;GetWindowThreadProcessId(h,&process);if(process==s.pid&&IsWindowVisible(h))++s.count;return TRUE;},LPARAM(&state));return state.count;}
uint32_t Capture(uint32_t pid){struct Search{uint32_t pid;HWND window;}search{pid,nullptr};EnumWindows([](HWND h,LPARAM raw)->BOOL{auto& s=*reinterpret_cast<Search*>(raw);DWORD process=0;GetWindowThreadProcessId(h,&process);if(process==s.pid&&IsWindowVisible(h))s.window=h;return TRUE;},LPARAM(&search));Check(search.window!=nullptr,"Own helper capture target");BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=200;info.bmiHeader.biHeight=-120;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;void* pixels=nullptr;const auto bitmap=CreateDIBSection(nullptr,&info,DIB_RGB_COLORS,&pixels,nullptr,0);const auto dc=CreateCompatibleDC(nullptr);Check(bitmap&&dc&&pixels,"Own native capture resources");const auto old=SelectObject(dc,bitmap);const auto printed=PrintWindow(search.window,dc,PW_CLIENTONLY);GdiFlush();const auto color=static_cast<uint32_t*>(pixels)[20*200+20]&0xFFFFFF;SelectObject(dc,old);DeleteDC(dc);DeleteObject(bitmap);Check(printed!=FALSE,"PrintWindow client rendering");return color;}
struct Client {Broker broker;uint64_t sequence=0;explicit Client(const std::filesystem::path& helper,uint64_t session):broker(helper,1,session){}
n::Packet Packet(n::Command c){n::Packet p;p.boot=1;p.session=broker.Enumeration().session;p.sequence=++sequence;p.pid=10;p.tid=20;p.command=c;return p;}
n::Reply Call(n::Command c){auto p=Packet(c);Check(broker.Exchange(p),"Native helper transport");Check(p.reply.restrictions==31,"Restricted token, low IL and job verified in helper");return p.reply;}};
n::Command Window(){n::Command c;c.op=n::Op::Window;c.rect={180,180,380,300};c.title[0]='A';return c;}
void Run(Client& client,uint64_t foreign){const auto w=client.Call(Window()).value;Check(Windows(client.broker.ProcessForTesting())==1,"Real separate native HWND visible");n::Command c;c.op=n::Op::Brush;c.color=0x2A7BCD;const auto brush=client.Call(c).value;c={};c.op=n::Op::Dc;c.target=w;const auto dc=client.Call(c).value;c={};c.op=n::Op::Fill;c.target=dc;c.object=brush;c.rect={10,10,80,80};Check(!client.Call(c).status,"Real host FillRect");c={};c.op=n::Op::Pixel;c.target=dc;c.rect={20,20,21,21};Check(client.Call(c).value==0x2A7BCD,"Host GetPixel matches native GDI drawing");Check(Capture(client.broker.ProcessForTesting())==0x2A7BCD,"Native HWND client contains the actual GDI drawing");c.target=foreign;Check(client.Call(c).status==6,"Foreign session ID rejected");c={};c.op=n::Op::ReleaseDc;c.target=dc;client.Call(c);c.op=n::Op::DeleteBrush;c.target=brush;client.Call(c);c.op=n::Op::DestroyWindow;c.target=w;client.Call(c);c={};c.op=n::Op::Finish;const auto done=client.Call(c);Check(done.completed&&done.calls[0]==1&&done.calls[3]==1&&done.calls[4]==1&&done.calls[7]==1,"Native call evidence and zero-resource completion");const auto pid=client.broker.ProcessForTesting();client.broker.Finish();Check(!Windows(pid),"All helper windows gone after completion");}}
int main(int argc,char** argv){try{Check(argc==2,"Helper argument");const auto helper=std::filesystem::absolute(argv[1]);Client a(helper,111),b(helper,222);Check(a.broker.ProcessForTesting()!=b.broker.ProcessForTesting(),"Distinct restricted helper processes");Run(a,(uint64_t(n::Kind::Dc)<<56)|(222ull<<32)|4);Run(b,(uint64_t(n::Kind::Dc)<<56)|(111ull<<32)|4);
    {Client x(helper,555),y(helper,666);const auto wx=x.Call(Window()).value,wy=y.Call(Window()).value;n::Command q;q.op=n::Op::Dc;q.target=wx;const auto dx=x.Call(q).value;q.target=wy;const auto dy=y.Call(q).value;Check(Windows(x.broker.ProcessForTesting())==1&&Windows(y.broker.ProcessForTesting())==1,"Two live native sessions");q={};q.op=n::Op::Pixel;q.rect={1,1,2,2};q.target=dy;Check(x.Call(q).status==6,"Actual live DC of another helper refused");q.target=dx;Check(y.Call(q).status==6,"Reverse live DC isolation");q={};q.op=n::Op::ReleaseDc;q.target=dx;x.Call(q);q.target=dy;y.Call(q);q.op=n::Op::DestroyWindow;q.target=wx;x.Call(q);q.target=wy;y.Call(q);q={};q.op=n::Op::Finish;x.Call(q);y.Call(q);x.broker.Finish();y.broker.Finish();}
    // CreateProcessAsUser initializes failure-path Windows DLL caches lazily.
    // Measure repeated failures after those process-wide caches are warm.
    for(unsigned i=0;i<3;++i){try{Broker missing(helper.wstring()+L".missing");}catch(const std::exception&){}}
    DWORD handlesBefore=0,handlesAfter=0;GetProcessHandleCount(GetCurrentProcess(),&handlesBefore);unsigned rejected=0;for(unsigned i=0;i<5;++i){try{Broker missing(helper.wstring()+L".missing");}catch(const std::exception&){++rejected;}}GetProcessHandleCount(GetCurrentProcess(),&handlesAfter);Check(rejected==5&&handlesAfter<=handlesBefore,"Repeated partial startup failures release parent handles");
    Client broken(helper,333);broken.Call(Window());const auto pid=broken.broker.ProcessForTesting();broken.broker.KillForTesting();auto p=broken.Packet(Window());Check(!broken.broker.Exchange(p),"Helper death fails channel");broken.broker.Finish();Check(!Windows(pid),"Helper death leaves no HWND");Client stalled(helper,444);stalled.broker.StallForTesting();auto pending=stalled.Packet(Window());const auto started=GetTickCount64();Check(!stalled.broker.Exchange(pending)&&GetTickCount64()-started<5000,"Unresponsive helper bounded timeout and termination");stalled.broker.Finish();std::cout<<checks<<" native GUI restricted process, native pixels, two sessions and helper death checks PASS\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
